from fastapi import FastAPI, Header
from fastapi.testclient import TestClient

app = FastAPI()

@app.get("/")
async def root(my_header: str = Header(convert_underscores=True)):
    return {"my_header": my_header}

client = TestClient(app)

def test_convert_underscores_true():
    # Should work: my-header (HTTP) -> my_header (Python)
    response = client.get("/", headers={"my-header": "foo"})
    print(f"Test hyphen: {response.json()} - Expected: {{'my_header': 'foo'}}")
    assert response.json() == {"my_header": "foo"}

    # Should NOT work: my_header (HTTP) -> my_header (Python) when convert_underscores=True
    # It should be a 422 since my_header is required.
    response = client.get("/", headers={"my_header": "foo"})
    print(f"Test underscore: {response.status_code} {response.json()} - Expected: 422")
    assert response.status_code == 422

def test_convert_underscores_false():
    # Create a separate app for this test
    app_false = FastAPI()
    @app_false.get("/")
    async def root_false(my_header: str = Header(convert_underscores=False)):
        return {"my_header": my_header}

    client_false = TestClient(app_false)

    # Should work: my_header (HTTP) -> my_header (Python)
    response = client_false.get("/", headers={"my_header": "foo"})
    print(f"Test underscore (false): {response.json()} - Expected: {{'my_header': 'foo'}}")
    assert response.json() == {"my_header": "foo"}

    # Should NOT work: my-header (HTTP) -> my_header (Python) when convert_underscores=False
    response = client_false.get("/", headers={"my-header": "foo"})
    print(f"Test hyphen (false): {response.status_code} - Expected: 422")
    assert response.status_code == 422

if __name__ == "__main__":
    try:
        test_convert_underscores_true()
        print("test_convert_underscores_true passed")
    except Exception as e:
        print(f"test_convert_underscores_true failed: {e}")

    try:
        test_convert_underscores_false()
        print("test_convert_underscores_false passed")
    except Exception as e:
        print(f"test_convert_underscores_false failed: {e}")

